<?php
namespace App\Catalog;
use App\Entity\CatalogSource; use App\Entity\Episode; use App\Entity\Season; use App\Entity\Series; use App\Repository\CatalogSourceRepository; use Doctrine\ORM\EntityManagerInterface; use Symfony\Component\RateLimiter\RateLimiterFactory; use Symfony\Contracts\Cache\CacheInterface; use Symfony\Contracts\Cache\ItemInterface;
final class CatalogService { public function __construct(private TvMazeCatalogProvider $provider,private CacheInterface $cache,private CatalogSourceRepository $sources,private EntityManagerInterface $em,private RateLimiterFactory $tvmazeApiLimiter){} /** @return list<array{id:string,title:string,summary:?string,posterUrl:?string,premiered:?string}> */ public function search(string $query):array{$key='catalog.tvmaze.search.'.hash('xxh3',mb_strtolower(trim($query)));return $this->cache->get($key,function(ItemInterface $item)use($query){$item->expiresAfter(3600);$this->guardRateLimit();return $this->provider->search($query);});} public function import(string $id):Series{$source=$this->sources->findByProviderId('tvmaze',$id);if($source?->isFresh())return $source->getSeries();$this->guardRateLimit();$payload=$this->provider->fetch($id);$series=$source?->getSeries()??new Series();$series->setTitle($payload['name'])->setSummary(isset($payload['summary'])?strip_tags((string)$payload['summary']):null)->setPosterUrl($payload['image']['original']??$payload['image']['medium']??null)->setStatus($payload['status']??null)->setGenres($payload['genres']??[])->setPremieredAt($this->date($payload['premiered']??null))->setEndedAt($this->date($payload['ended']??null));$series->touch();$seasons=[];foreach(($payload['_embedded']['seasons']??[]) as $row){$number=(int)$row['number'];$season=new Season($number);$season->setName($row['name']??null);$series->addSeason($season);$seasons[$number]=$season;}foreach(($payload['_embedded']['episodes']??[]) as $row){$number=(int)($row['number']??0);$season=$seasons[(int)($row['season']??0)]??null;if(!$season||$number<1)continue;$episode=new Episode($number);$episode->setTitle($row['name']??'Épisode '.$number);$episode->setSummary(isset($row['summary'])?strip_tags((string)$row['summary']):null);$episode->setAirDate($this->date($row['airdate']??null));$season->addEpisode($episode);}if(!$source){$source=new CatalogSource('tvmaze',$id,$series);$this->em->persist($source);}$source->refresh($payload,new \DateTimeImmutable('+24 hours'));$this->em->persist($series);$this->em->flush();return $series;} private function guardRateLimit():void{if(!$this->tvmazeApiLimiter->create('catalog')->consume()->isAccepted())throw new \RuntimeException('La limite TVmaze est temporairement atteinte. Réessayez dans un instant.');} private function date(?string $value):?\DateTimeImmutable{return $value?new \DateTimeImmutable($value):null;} }
